import React, { useState } from 'react';
import { signIn } from '../utils/api';

export default function LoginPage() {
  const [email,    setEmail]    = useState('');
  const [password, setPassword] = useState('');
  const [error,    setError]    = useState('');
  const [loading,  setLoading]  = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    const { error } = await signIn(email, password);
    if (error) setError(error.message === 'Invalid login credentials'
      ? 'Email ou senha incorretos.' : error.message);
    setLoading(false);
  };

  return (
    <div style={{
      minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center',
      background:'var(--bg)', padding:20,
    }}>
      <div style={{width:'100%',maxWidth:380}}>
        {/* Logo */}
        <div style={{textAlign:'center',marginBottom:32}}>
          <div style={{fontSize:40,marginBottom:8}}>📊</div>
          <div style={{fontSize:22,fontWeight:700,color:'var(--text)'}}>BetTracker Pro</div>
          <div style={{fontSize:13,color:'var(--text2)',marginTop:4}}>Acesso por convite</div>
        </div>

        {/* Card */}
        <div className="card" style={{padding:28}}>
          <div style={{fontWeight:700,fontSize:16,marginBottom:20}}>Entrar na sua conta</div>

          <form onSubmit={handleLogin} style={{display:'flex',flexDirection:'column',gap:14}}>
            <div className="form-group">
              <span className="form-label">Email</span>
              <input type="email" value={email} onChange={e=>setEmail(e.target.value)}
                placeholder="seu@email.com" required autoFocus />
            </div>
            <div className="form-group">
              <span className="form-label">Senha</span>
              <input type="password" value={password} onChange={e=>setPassword(e.target.value)}
                placeholder="••••••••" required />
            </div>

            {error && (
              <div style={{background:'var(--red-bg)',color:'var(--red)',padding:'8px 12px',
                borderRadius:'var(--radius-sm)',fontSize:13}}>
                {error}
              </div>
            )}

            <button className="btn btn-primary" type="submit" disabled={loading}
              style={{width:'100%',justifyContent:'center',padding:'10px'}}>
              {loading ? 'Entrando…' : 'Entrar'}
            </button>
          </form>
        </div>

        <div style={{textAlign:'center',marginTop:16,fontSize:12,color:'var(--text3)'}}>
          Não tem acesso? Solicite um convite ao administrador.
        </div>
      </div>
    </div>
  );
}
